/**
 * Unit tests for ParserBase._reportTooLongIntegral.
 * Since the method is protected and belongs to an abstract class, 
 * we use a Spy of a concrete implementation or a subclass.
 */
public class ParserBase__reportTooLongIntegral_TriageGen1Test {

    private ParserBase parserBaseSpy;
    private static final int NR_INT = 0; // Assuming standard Jackson constants
    private static final int NR_LONG = 1;

    // Concrete implementation of the abstract ParserBase for testing purposes
    private static class TestParserBase extends ParserBase {
        protected TestParserBase(IOContext ctxt, int features) {
            super(ctxt, features);
        }

        @Override
        protected void _closeInput() throws IOException {}

        @Override
        protected void _releaseBuffers() throws IOException {}

        @Override
        protected void _handleEOF() throws com.fasterxml.jackson.core.JsonParseException {
        }

        // Mocking the internal helper to avoid complex logic in test
        // In a real scenario, _longIntegerDesc is likely a private/protected method in the same class
        // We will rely on the spy to intercept _reportError
    }

    @Before
    public void setUp() {
        IOContext ctxt = Mockito.mock(IOContext.class);
        parserBaseSpy = spy(new TestParserBase(ctxt, 0));
    }

    /**
     * Tests the branch where expType is NR_LONG.
     * Validates that the error message contains "long".
     */
    @Test
    public void testReportTooLongIntegral_LongType() throws Exception {
        int expType = NR_LONG;
        String rawNum = "9223372036854775808"; // Long.MAX_VALUE + 1

        invokeReportTooLongIntegral(expType, rawNum);

        // Verify _reportError is called with the correct type string "long"
        verify(parserBaseSpy)._reportError(
                eq("Numeric value (%s) out of range of %s"), 
                anyString(), 
                eq("long")
        );
    }

    /**
     * Tests the branch where expType is NOT NR_LONG (e.g., NR_INT).
     * Validates that the error message contains "int".
     */
    @Test
    public void testReportTooLongIntegral_IntType() throws Exception {
        int expType = NR_INT;
        String rawNum = "2147483648"; // Integer.MAX_VALUE + 1

        invokeReportTooLongIntegral(expType, rawNum);

        // Verify _reportError is called with the correct type string "int"
        verify(parserBaseSpy)._reportError(
                eq("Numeric value (%s) out of range of %s"), 
                anyString(), 
                eq("int")
        );
    }

    /**
     * Tests that the method correctly throws IOException if _reportError throws it.
     */
    @Test(expected = IOException.class)
    public void testReportTooLongIntegral_ThrowsIOException() throws Exception {
        int expType = NR_LONG;
        String rawNum = "123";

        // Force _reportError to throw IOException
        doThrow(new IOException("Simulated error"))
                .when(parserBaseSpy)._reportError(anyString(), anyString(), anyString());

        invokeReportTooLongIntegral(expType, rawNum);
    }

    /**
     * Helper method to access the protected method via reflection.
     */
    private void invokeReportTooLongIntegral(int expType, String rawNum) throws Exception {
        Method method = ParserBase.class.getDeclaredMethod("_reportTooLongIntegral", int.class, String.class);
        method.setAccessible(true);
        try {
            method.invoke(parserBaseSpy, expType, rawNum);
        } catch (java.lang.reflect.InvocationTargetException e) {
            if (e.getCause() instanceof IOException) {
                throw (IOException) e.getCause();
            }
            throw e;
        }
    }
}
